interface Clock { now(): number }

class ConfigurableClock implements Clock {
  constructor(private instant: number, private fail = false) {}
  now(): number {
    if (this.fail) throw new Error('clock unavailable');
    return this.instant;
  }
}

const clock = new ConfigurableClock(epoch, true);
